function makeExamDocx(tests,{teacher=false}={}){if(!tests?.length)throw Error('Chưa có đề để xuất Word.');const out=[paragraph('EDUPLAN AI – ĐỀ KIỂM TRA HÓA HỌC','title'),paragraph('Tác giả giải pháp: Lê Bá Nhẫn – Trường THPT Hòn Đất','subtitle'),paragraph(teacher?'BẢN GIÁO VIÊN – CÓ ĐÁP ÁN, LỜI GIẢI':'BẢN HỌC SINH – KHÔNG CÓ ĐÁP ÁN','meta')];for(let tix=0;tix<tests.length;tix++){const t=tests[tix],qs=t.questions||[];if(tix)out.push(paragraph('', 'page'));out.push(paragraph(`${t.title||'Đề kiểm tra'} – Mã đề ${t.code||t.share_code||tix+1}`,'h1'));out.push(paragraph(`Khối: ${t.grade} | Loại đề: ${t.kind||t.exam_kind||'Theo bài/chương'} | Số câu: ${qs.length} | Số mã đề: ${tests.length}`,'meta'));out.push(paragraph(`Chương: ${t.chapter||'Tổng hợp'} | Bài: ${t.lesson||'Toàn chương'}`,'meta'));out.push(paragraph(`Phân hóa: ${['NB','TH','VD','VDC'].map(d=>`${fullLevel(d)} ${qs.filter(q=>q.difficulty===d).length}`).join(' • ')}`,'meta'));if(t.duration_minutes)out.push(paragraph(`Thời gian: ${t.duration_minutes} phút`,'meta'));out.push(paragraph('Họ và tên: ............................................................................ Lớp: ................'));for(let i=0;i<qs.length;i++)out.push(...qBody(qs[i],i,true));if(teacher){out.push(paragraph('ĐÁP ÁN VÀ HƯỚNG DẪN GIẢI','h1'));qs.forEach((q,i)=>{out.push(paragraph(`Câu ${i+1}: ${q.correct??q.answer??'Chưa có đáp án'}`,'h2'));out.push(paragraph(q.explanation||'Chưa có lời giải được duyệt.'));});}}return docx(out);}
