function esc(s){return String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;')}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{}}
function toast(msg){const node=document.getElementById('notice');if(node){node.textContent=msg;node.style.display='block';node.scrollIntoView({behavior:'smooth',block:'nearest'})}}
function level(l){return {NB:'Nhận biết',TH:'Thông hiểu',VD:'Vận dụng',VDC:'Vận dụng cao'}[l]||l}
function quota(total,percent){const levels=['NB','TH','VD','VDC'], raw=levels.map(k=>total*(percent[k]||0)/100),out=raw.map(Math.floor);let left=total-out.reduce((a,b)=>a+b,0);const order=levels.map((_,i)=>i).sort((a,b)=>raw[b]%1-raw[a]%1||a-b);for(let i=0;i<left;i++)out[order[i]]++;return Object.fromEntries(levels.map((k,i)=>[k,out[i]]))}
function shuffle(arr){const out=arr.slice();for(let i=out.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[out[i],out[j]]=[out[j],out[i]]}return out}
function navigate(tab){state.tab=tab;state.pageViews=(Number(state.pageViews)||0)+1;testResult=null;persist();render()}
function setGrade(v){state.grade=Number(v);state.chapter='';state.lesson='';persist();render()}
function card(name,desc,emoji,tab){return `<button class="quick" onclick="navigate('${tab}')"><span class="ic">${emoji}</span><strong>${name}</strong><span>${desc}</span></button>`}
function heading(title,subtitle){return `<h1 class="heading">${esc(title)}</h1><p class="muted">${esc(subtitle)}</p>`}
function chapterList(){return CURRICULUM[String(state.grade)]||[]}
function activeLessons(){return chapterList().find(c=>c.name===state.chapter)?.lessons||[]}
function chapterOptionsDemo(){return '<option value="">Tất cả chương</option>'+chapterList().map(c=>`<option value="${esc(c.name)}" ${state.chapter===c.name?'selected':''}>Chương ${c.no}. ${esc(c.name)}</option>`).join('')}
function lessonOptionsDemo(){return '<option value="">Tất cả bài</option>'+activeLessons().map(l=>`<option value="${esc(l.name)}" ${state.lesson===l.name?'selected':''}>Bài ${l.no}. ${esc(l.name)}</option>`).join('')}
