function catalog(){return `${heading('Mục lục SGK Hóa học KNTT 10, 11, 12','Đầy đủ 7/23 bài Hóa 10, 6/25 bài Hóa 11 và 8/30 bài Hóa 12. Chỉ là tên chương, bài; không sao chép nội dung có bản quyền.')}
 <div class="panel"><div class="row"><label class="field">Khối lớp<select onchange="setGrade(this.value)">${[10,11,12].map(g=>`<option value="${g}" ${g===state.grade?'selected':''}>Hóa ${g}</option>`).join('')}</select></label><label class="field">Tìm kiếm tên chương / bài<input id="catalogSearch" placeholder="Gõ từ khóa..." oninput="filterCatalog(this.value)"/></label><span class="pill">${chapterList().length} chương • ${chapterList().reduce((n,c)=>n+c.lessons.length,0)} bài</span></div></div>
 <div id="catalogItems">${chapterList().map(c=>`<div class="card" style="margin:12px 0" data-title="${esc((c.name+' '+c.lessons.map(l=>l.name).join(' ')).toLocaleLowerCase('vi'))}"><h3><span class="pill">CHƯƠNG ${c.no}</span> ${esc(c.name)}</h3>${c.lessons.map(l=>`<div class="history-item"><span><b>Bài ${l.no}.</b> ${esc(l.name)}</span><div class="row" style="margin:0"><button class="btn secondary" onclick="chooseLesson(${JSON.stringify(c.name).replaceAll('"','&quot;')},${JSON.stringify(l.name).replaceAll('"','&quot;')},'create')">Tạo đề</button><button class="btn secondary" onclick="chooseLesson(${JSON.stringify(c.name).replaceAll('"','&quot;')},${JSON.stringify(l.name).replaceAll('"','&quot;')},'bank')">Câu hỏi</button><button class="btn secondary" onclick="hub69Nav('practice',${JSON.stringify(c.name).replaceAll('"','&quot;')},${JSON.stringify(l.name).replaceAll('"','&quot;')})">Tự luyện</button><button class="btn secondary" onclick="hub69Nav('smart',${JSON.stringify(c.name).replaceAll('"','&quot;')},${JSON.stringify(l.name).replaceAll('"','&quot;')})">Luyện 5 câu</button></div></div>`).join('')}</div>`).join('')}</div>`}
