function home(){const drafts=state.bank.filter(x=>x.verified).length;return `<div class="hero"><div><span class="pill">WEBAPP HÓA HỌC THPT • V7.0</span><h1>Giảng dạy khoa học, đánh giá thông minh.</h1><p>Một không gian chung để xây dựng ma trận đề, phân hóa câu hỏi, làm bài và phân tích lỗi sai của học sinh Hóa 10–11–12.</p></div><div class="hero-art">⚛</div></div><div class="metrics"><div class="metric"><small>Câu hỏi đã được duyệt</small><strong>${drafts}</strong><span>Ngân hàng tại trình duyệt này</span></div><div class="metric"><small>Đề đã tạo</small><strong>${state.exams.length}</strong><span>Trộn câu và phương án</span></div><div class="metric"><small>Lượt mở WebApp trên máy này</small><strong>${state.visits}</strong><span>Không phải truy cập website online</span></div><div class="metric"><small>Bài nộp thử</small><strong>${state.attempts.length}</strong><span>Điểm tối đa 10</span></div></div><h3>Truy cập nhanh</h3><div class="cards">${card('Tạo phiếu học tập','Theo chương/bài KNTT, NLS/AI','▧','worksheet')}${card('Công cụ Hóa học','Khối lượng mol, nồng độ, cân bằng PTHH','⚗','chem')}${card('Gọi tên ngẫu nhiên','Hạn chế lặp tên trong một vòng','♧','random')}${card('Tạo & trộn đề kiểm tra','Ma trận 4 mức độ và nhiều mã đề','▤','create')}${card('Kiểm tra trực tuyến','Làm bài, nộp bài, xem đáp án','✎','test')}${card('Kết quả & phân tích','Báo cáo điểm và lỗi sai','▥','results')}${card('Trợ lý AI Hóa học','Tính năng online trong bộ triển khai','✧','ai')}${card('Học liệu tham khảo','PhET, PubChem, IUPAC và học liệu mở','▣','docs')}${card('Luyện tập tương tác','Câu hỏi tự luyện với phản hồi','★','practice')}${card('Luyện từng câu và nhóm 5/10/15','Tự chuyển câu, lưu tiến độ, xem lỗi sai','★','smart')}</div>`}
function bank(){
 const rows=filteredDemo();const sourceRows=rows.filter(q=>q.source_id);const vetted=rows.filter(q=>q.verified&&q.answer&&['NB','TH','VD','VDC'].includes(q.difficulty));
 const page=Math.max(0,Number(bankPage61)||0),pageSize=20,visible=rows.slice(page*pageSize,(page+1)*pageSize);
 return `${heading('Ngân hàng câu hỏi tập trung – TÀI LIỆU THẬT - V6.6','67 tệp Word, 1.958 câu nguồn. 18 đề Hóa 10–11 mới, 81 câu đã đối chiếu nội dung; các câu có MathType/hình/khóa thiếu vẫn chờ rà soát. Đã có gợi ý tên bài và mức độ từng câu; câu chưa đủ bằng chứng được gắn cờ. Chỉ phê duyệt câu có khóa đáp án đã giải/đối chiếu.')}
 <div class="notice warning"><b>Quy tắc chất lượng:</b> ${state.bank.filter(x=>x.verified&&x.answer).length} câu đã có đáp án được rà soát; ${state.bank.filter(x=>x.proposed_answer&&!x.verified).length} câu có đáp án đề xuất; các câu còn lại cần giải và xác minh. Nhãn bài/mức độ tự động là gợi ý, chưa phải chứng nhận học thuật. Hình/bảng được lưu trong nguyên bản DOCX ở gói nguồn; kiểm tra bản xuất Word trước khi phát.</div>
 <div class="panel"><div class="row"><label class="field">Khối<select onchange="setGrade(this.value);bankPage61=0">${[10,11,12].map(g=>`<option ${g===state.grade?'selected':''} value="${g}">Hóa ${g}</option>`).join('')}</select></label><label class="field">Chương<select onchange="setChapter(this.value);bankPage61=0">${chapterOptionsDemo()}</select></label><label class="field">Bài<select onchange="setLesson(this.value);bankPage61=0">${lessonOptionsDemo()}</select></label><button class="btn secondary" onclick="downloadBank()">↓ Sao lưu dữ liệu JSON</button><label class="btn secondary">↑ Nhập JSON<input hidden type="file" accept=".json" onchange="importBankFile(this)"></label></div>
 <div class="row"><span class="pill">${rows.length} câu phù hợp</span><span class="pill ok">${vetted.length} câu có thể xét dùng ra đề</span><span class="pill warn">${sourceRows.filter(q=>!q.verified).length} câu nguồn chưa duyệt / chờ xác minh</span></div>
 <p class="muted">Phân loại gợi ý toàn bộ câu theo bài; câu liên bài hoặc chưa rõ được xếp tạm vào Ôn tập chương và có cờ xác minh. Chỉ xuất đề từ những câu đã duyệt.</p></div>
 <div class="panel"><div class="row"><button class="btn secondary" onclick="bankPage61=Math.max(0,bankPage61-1);render()">Trang trước</button><span>Trang ${page+1}/${Math.max(1,Math.ceil(rows.length/pageSize))}</span><button class="btn secondary" onclick="bankPage61=Math.min(Math.ceil(rows.length/pageSize)-1,bankPage61+1);render()">Trang sau</button></div>
 ${visible.map(q=>`<div class="q"><div class="row"><span class="pill ${q.verified?'ok':'warn'}">${q.verified?'Đã duyệt':'Chờ duyệt'}</span><span class="pill">${esc(q.kind)}</span><span class="pill">${esc(q.difficulty)}</span></div><small>${esc(q.source_title||'Câu đã có')} • Chương: ${esc(q.chapter)} • Bài: ${esc(q.lesson||'CHƯA GÁN')}</small><h4>${esc(q.stem).slice(0,1100)}${q.stem.length>1100?'…':''}</h4><div class="row"><button class="btn secondary" onclick="reviewBank61('${esc(q.id)}')">${q.verified?'Xem/Chỉnh sửa':'Kiểm tra – Phân loại – Gắn đáp án'}</button>${q.flags?.length?`<span class="pill warn">${q.flags.length} vấn đề cần kiểm chứng</span>`:''}</div></div>`).join('')||'<p>Không có câu trong mục này.</p>'}</div>`;
}
let bankPage61=0;
function embedMedia61(htmltext){return String(htmltext||'').replace(/<img[^>]*data-img="([^"]+)"[^>]*>/g,(_m,k)=>{const m=(EDUPLAN_MEDIA_61[k]||EDUPLAN_MEDIA_62[k]||EDUPLAN_MEDIA_64[k]||EDUPLAN_MEDIA_65[k]||EDUPLAN_MEDIA_66[k]);return m?`<img class="source-image" src="${m.path||(`data:${m.mime};base64,${m.data}`)}" alt="Hình minh họa nguồn"/>`:'<b>Không có tệp hình.</b>';});}
function reviewBank61(id){const q=state.bank.find(x=>x.id===id);if(!q)return;const chap=CURRICULUM[String(q.grade)]?.find(c=>c.name===q.chapter);const current=chap?.lessons||[];
 const old=document.getElementById('bankModal61');if(old)old.remove();const layer=document.createElement('div');layer.id='bankModal61';layer.className='bank-modal61';
 const rich=(EDUPLAN_SOURCE_HTML_61[id]||EDUPLAN_SOURCE_HTML_62[id]||EDUPLAN_SOURCE_HTML_64[id]||EDUPLAN_SOURCE_HTML_65[id]||EDUPLAN_SOURCE_HTML_66[id]);
 layer.innerHTML=`<div class="bank-dialog61"><div class="row"><h2 style="flex:1">Thẩm định câu hỏi nguồn</h2><button class="btn secondary" onclick="document.getElementById('bankModal61').remove()">Đóng</button></div>
 <p class="muted">${esc(q.source_title||'Câu bổ sung')} • ID ${esc(q.id)} • Nguồn ${esc(q.source_question_number||'')}</p>
 <div class="source-rich61">${rich?embedMedia61(rich):`<p>${esc(q.stem)}</p>`}</div>
 <p class="notice warning">Phân loại: ${esc(q.classification_confidence||'chưa rõ')} • Đáp án: ${q.verified?'đã kiểm tra nội dung':'chưa duyệt'}${q.proposed_answer&&!q.verified?' • Đề xuất '+esc(q.proposed_answer):''}. Gợi ý AI/biên soạn phải được đối chiếu với tài liệu gốc trước khi dùng cho kiểm tra chính thức.</p>
 <div class="row"><label class="field">Bài học chính<select id="edit-lesson61"><option value="">Chỉ gán cấp chương – chưa xác định bài</option>${current.map(l=>`<option value="${esc(l.name)}" ${q.lesson===l.name?'selected':''}>Bài ${l.no}. ${esc(l.name)}</option>`).join('')}</select></label><label class="field">Mức độ<select id="edit-level61">${[['UNCLASSIFIED','Chưa phân loại'],['NB','Nhận biết'],['TH','Thông hiểu'],['VD','Vận dụng tính toán'],['VDC','Vận dụng cao tính toán']].map(([v,n])=>`<option value="${v}" ${v===q.difficulty?'selected':''}>${n}</option>`).join('')}</select></label></div>
 ${q.kind==='mcq'?`<div class="two">${'ABCD'.split('').map(k=>`<label class="field">Phương án ${k}<textarea id="edit-opt61-${k}" rows="2">${esc(q.options?.[k]||'')}</textarea></label>`).join('')}</div>`:''}
 <label class="field">${q.kind==='essay'?'Hướng dẫn chấm / đáp án tự luận':q.kind==='tf4'?'Đáp án 4 ý (ví dụ D,S,D,S)':q.kind==='mcq'?'Đáp án đúng (A, B, C hoặc D)':'Đáp án trả lời ngắn'}<input id="edit-answer61" value="${esc(q.answer||q.proposed_answer||'')}" placeholder="Nhập đáp án đã đối chiếu"></label>
 <label class="field">Hướng dẫn giải / bằng chứng thẩm định<textarea id="edit-explain61" rows="3">${esc(q.explanation||q.proposed_explanation||'')}</textarea></label>
 <label style="display:block;margin:10px 0;font-weight:600"><input type="checkbox" id="edit-enable-practice" ${q.practice_enabled?'checked':''}> Cho phép dùng câu đã duyệt để luyện tập từng câu/nhóm 5 câu</label><p class="notice warning">Chỉ nhấn Duyệt khi đã đối chiếu đáp án, mức độ và cách hiển thị. Câu có hình/bảng cần so sánh với file DOCX gốc trước khi xuất Word.</p>
 <div class="row"><button class="btn" onclick="saveReview61('${esc(id)}',true)">Lưu và duyệt</button><button class="btn secondary" onclick="saveReview61('${esc(id)}',false)">Lưu bản nháp</button></div></div>`;
 document.body.appendChild(layer);
}
function saveReview61(id,approve){const q=state.bank.find(x=>x.id===id);if(!q)return;const lesson=document.getElementById('edit-lesson61').value,level=document.getElementById('edit-level61').value,answer=document.getElementById('edit-answer61').value.trim(),explain=document.getElementById('edit-explain61').value.trim();let opts=q.options||{};
 if(q.kind==='mcq')opts=Object.fromEntries('ABCD'.split('').map(k=>[k,document.getElementById('edit-opt61-'+k).value.trim()]));
 if(approve){if(!['NB','TH','VD','VDC'].includes(level)){toast('Phải xác nhận mức độ.');return}if(!answer){toast('Bản học sinh không có đáp án. Hãy nhập đáp án được kiểm chứng.');return}if(q.kind==='mcq'&&(!['A','B','C','D'].includes(answer.toUpperCase())||'ABCD'.split('').some(k=>!opts[k]))){toast('Câu A–D cần bốn phương án và đáp án A/B/C/D.');return}if(q.kind==='tf4'&&!/^([DdSs][,;\s]*){4}$/.test(answer.replace(/[Đđ]/g,'D'))){toast('Đúng/Sai 4 ý: nhập D,S,D,S');return}if(!lesson&&!confirm('Câu chưa gán bài cụ thể. Duyệt ở cấp chương để chỉ sử dụng cho đề theo chương?'))return;}
 q.lesson=lesson;q.difficulty=level;q.answer=q.kind==='mcq'?answer.toUpperCase():answer;q.explanation=explain;q.options=opts;q.verified=!!approve;q.review_status=approve?'APPROVED':'PENDING';q.practice_enabled=!!approve&&!!document.getElementById('edit-enable-practice')?.checked;q.classification_status=lesson?'LESSON_ASSIGNED':'CHAPTER_ONLY';
 try{persist()}catch(e){toast('Không lưu được: '+e.message);return}document.getElementById('bankModal61').remove();render();toast(approve?'Đã duyệt và lưu câu hỏi.':'Đã lưu bản nháp.');}

function approveDemo(id){const q=state.bank.find(q=>q.id===id);if(!q)return;const ch=chapterList().some(c=>c.name===q.chapter&&c.lessons.some(l=>l.name===q.lesson));if(Number(q.grade)!==state.grade||!ch){toast('Câu chưa khớp khối/chương/bài KNTT; kiểm tra nguồn JSON trước khi duyệt.');return}if(!confirm('Bạn đã kiểm tra đáp án, công thức và nguồn câu hỏi?'))return;q.verified=true;persist();render();toast('Đã duyệt câu này.')}
function downloadBank(){const b=new Blob([JSON.stringify(state.bank,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='EduPlan_AI_5_5_Demo_Bank.json';a.click();URL.revokeObjectURL(a.href)}
function importBankFile(input){const f=input.files?.[0];if(!f)return;if(f.size>3000000){toast('Tệp quá lớn (tối đa 3 MB).');input.value='';return;}f.text().then(raw=>{try{const obj=JSON.parse(raw),all=Array.isArray(obj)?obj:(obj.questions||obj.bank||[]);if(!Array.isArray(all))throw Error('Tệp cần có danh sách questions hoặc bank.');const known=new Set(state.bank.map(x=>x.grade+'|'+x.stem.trim().toLowerCase()));let added=0;for(const src of all.slice(0,1000)){const grade=Number(src.grade??src.g),opts=src.options||{},stem=String(src.stem||src.question||'').trim(),answer=String(src.answer||'').trim(),kind=src.kind||'mcq';if(![10,11,12].includes(grade)||!stem||!answer||!['NB','TH','VD','VDC'].includes(src.difficulty||src.level||'TH'))continue;if(kind==='mcq'&&(!'ABCD'.includes(answer)||['A','B','C','D'].some(k=>!opts[k])))continue;const fingerprint=grade+'|'+stem.toLowerCase();if(known.has(fingerprint))continue;known.add(fingerprint);state.bank.push({grade,chapter:src.chapter||'',lesson:src.lesson||'',stem,options:opts,answer,explanation:src.explanation||'',kind,difficulty:src.difficulty||src.level||'TH',nls_tags:src.nls_tags||[],verified:false,practice_enabled:false,id:'IMP'+Date.now().toString(36)+added});added++;}persist();render();toast('Đã nhập '+added+' câu vào bản dùng thử ở trạng thái CHỜ DUYỆT. Cần kiểm tra trước khi dùng; bản HTML không phát hành online.')}catch(e){toast('Không nhập được: '+e.message)}finally{input.value=''}})}
function questionPool(mode,grade,chapter,lesson){return state.bank.filter(q=>Number(q.grade)===Number(grade) &&q.verified===true&& q.kind==='mcq' && (!chapter||q.chapter===chapter)&&(!lesson||q.lesson===lesson));}
function worksheetPool61(grade,chapter,lesson){return state.bank.filter(q=>Number(q.grade)===Number(grade)&&q.verified===true&&['NB','TH','VD','VDC'].includes(q.difficulty)&&(!chapter||q.chapter===chapter)&&(!lesson||q.lesson===lesson));}
function getFrozenQuestions(t){if(Array.isArray(t.questions)&&t.questions.length)return t.questions;return (t.ids||[]).map(id=>{const q=state.bank.find(q=>q.id===id);return q?displayQ(q,t):null}).filter(Boolean);}
function create(){return `${heading('Tạo và trộn đề kiểm tra','Tự rút câu đã DUYỆT theo đúng khối, chương, bài, loại đề, số câu và mức độ; sau khi tạo mã đề được lưu vào mục Làm bài kiểm tra và có thể tải Word.') }
<div class="panel"><div class="row"><label class="field">Khối lớp<select onchange="setGrade(this.value)">${[10,11,12].map(g=>`<option value="${g}" ${g===state.grade?'selected':''}>Hóa ${g}</option>`).join('')}</select></label><label class="field">Loại đề<select id="kind"><option>Kiểm tra theo bài</option><option>Kiểm tra theo chương</option><option>Kiểm tra thường xuyên</option><option>Giữa học kì I</option><option>Giữa học kì II</option></select></label><label class="field">Số câu<input id="amount" type="number" min="1" max="80" value="4" oninput="drawMatrix()"/></label><label class="field">Số mã đề<input id="variants" type="number" min="1" max="6" value="2"/></label></div>
<div class="row"><label class="field">Chương SGK KNTT<select id="chapter" onchange="setChapter(this.value)">${chapterOptionsDemo()}</select></label><label class="field">Bài SGK KNTT<select id="lesson" onchange="setLesson(this.value)">${lessonOptionsDemo()}</select></label></div>
<label class="field">Tên đề<input id="exam-title" value="Kiểm tra Hóa học ${state.grade}"/></label>
<div class="matrixbox"><h3>Mức độ phân hóa (tổng 100%)</h3><div class="grid4">${['NB','TH','VD','VDC'].map((k,i)=>`<div class="mcell"><b>${level(k)}</b><label class="field">Tỉ lệ (%)<input type="number" min="0" max="100" id="pct-${k}" value="${[30,40,20,10][i]}" oninput="drawMatrix()"/></label><strong id="quota-${k}">–</strong><small id="available-${k}"></small></div>`).join('')}</div><div id="matrixWarn" class="aside-note"></div></div>
<div class="row"><button class="btn" onclick="generateExam()">Tạo đề • Lưu • Xuất Word (.docx)</button><button class="btn secondary" onclick="navigate('bank')">Nhập/Duyệt ngân hàng câu hỏi</button></div><p class="muted">Nếu thiếu câu đúng mức độ, WebApp không tự lấy câu sai phạm vi; tra cứu nguồn và AI bổ sung ở phiên bản máy chủ, giáo viên phải duyệt trước khi sử dụng.</p></div>
<div class="panel"><h3>Đề đã tạo (có ngay trong Làm bài kiểm tra)</h3>${state.exams.length?`<div class="tablewrap"><table><thead><tr><th>Mã đề</th><th>Tên đề</th><th>Khối, chương, bài</th><th>Số câu</th><th>Hành động</th></tr></thead><tbody>${state.exams.map(t=>`<tr><td><b>${esc(t.code)}</b></td><td>${esc(t.title)}</td><td>Hóa ${t.grade} • ${esc(t.chapter||'Tổng hợp')} • ${esc(t.lesson||'Toàn chương')}</td><td>${getFrozenQuestions(t).length}</td><td><button class="btn secondary" onclick="openTest('${t.code}')">Làm bài</button> <button class="btn secondary" onclick="exportExamDocx('${t.code}',false)">Word HS</button> <button class="btn secondary" onclick="exportExamDocx('${t.code}',true)">Word GV</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">Chưa có đề. Thẩm định và duyệt đáp án câu hỏi nguồn trước khi tạo đề.</p>'}</div>`;}
function drawMatrix(){const e=document.getElementById('amount');if(!e)return;const n=Math.max(1,Math.trunc(Number(e.value)||1));const pct=Object.fromEntries(['NB','TH','VD','VDC'].map(k=>[k,Math.max(0,Number(document.getElementById('pct-'+k)?.value)||0)]));const total=Object.values(pct).reduce((a,b)=>a+b,0),q=quota(n,pct),pool=questionPool('',state.grade,state.chapter,state.lesson);const lacks=[];for(const k of ['NB','TH','VD','VDC']){const a=pool.filter(x=>x.difficulty===k).length;document.getElementById('quota-'+k).textContent=q[k]+' câu';document.getElementById('available-'+k).textContent='Có '+a+' câu đã duyệt';if(q[k]>a)lacks.push(level(k)+' thiếu '+(q[k]-a));}document.getElementById('matrixWarn').textContent='Tổng ma trận: '+total+'% • '+(lacks.join('; ')||'Đủ câu theo mức độ.');}
function generateExam(){const count=Number(document.getElementById('amount').value),n=Number(document.getElementById('variants').value);if(!Number.isInteger(count)||count<1||count>80||!Number.isInteger(n)||n<1||n>6){toast('Số câu 1–80, số mã đề 1–6.');return}const pct=Object.fromEntries(['NB','TH','VD','VDC'].map(k=>[k,Number(document.getElementById('pct-'+k).value)||0]));if(Object.values(pct).reduce((a,b)=>a+b,0)!==100){toast('Tỉ lệ phân hóa phải đúng 100%.');return}const kind=document.getElementById('kind').value;if(kind==='Kiểm tra theo bài'&&!state.lesson){toast('Đề theo bài phải chọn bài học.');return}if(kind==='Kiểm tra theo chương'&&!state.chapter){toast('Đề theo chương phải chọn chương.');return}const chosen=[],q=quota(count,pct),pool=questionPool(kind,state.grade,state.chapter,state.lesson);for(const k of ['NB','TH','VD','VDC']){const got=shuffle(pool.filter(x=>x.difficulty===k)).slice(0,q[k]);if(got.length<q[k]){toast('Thiếu câu đã duyệt '+level(k)+': cần '+q[k]+', có '+got.length+'. Mở ngân hàng câu hỏi để bổ sung và duyệt trước khi tạo.');return}chosen.push(...got);}const title=document.getElementById('exam-title').value.trim()||'Kiểm tra Hóa học',group=crypto.randomUUID?.()||String(Date.now()),variants=[];for(let i=0;i<n;i++){const code=('DE'+Date.now().toString(36)+Math.random().toString(36).slice(2,6)).toUpperCase();let questions=shuffle(chosen.map(orig=>{const order=shuffle(['A','B','C','D']);return {...structuredClone(orig),options:Object.fromEntries(['A','B','C','D'].map((lab,j)=>[lab,orig.options[order[j]]])),answer:['A','B','C','D'][order.indexOf(orig.answer)]}}));variants.push({code,group,grade:state.grade,title,kind,chapter:state.chapter,lesson:state.lesson,questions,ids:questions.map(q=>q.id),created:new Date().toISOString(),pct});}state.exams.push(...variants);persist();try{saveDocx(makeExamDocx(variants),`EduPlan_De_Hoa${state.grade}_${variants.length}_Ma_HS.docx`)}catch(e){toast('Đã lưu đề nhưng chưa tải được Word: '+e.message)}render();toast('Đã tạo '+n+' mã đề, tự lưu vào Làm bài kiểm tra và tải Word HS. Word GV có nút xuất riêng để bảo mật đáp án.');}
function exportExamDocx(code,teacher=false){const t=getTest(code);if(!t){toast('Không tìm thấy mã đề');return}const variants=state.exams.filter(x=>x.group===t.group);try{saveDocx(makeExamDocx(variants.length?variants:[t],{teacher}),`EduPlan_Hoa${t.grade}_${t.code}_${teacher?'GV':'HS'}.docx`)}catch(e){toast('Lỗi xuất Word: '+e.message)}}
function getTest(code){return state.exams.find(x=>x.code===code)}
function displayQ(q,t){if(t.questions){return t.questions.find(x=>x.id===q.id)||q}const orders=t.orders?.[q.id]||['A','B','C','D'];return {...q,options:Object.fromEntries(['A','B','C','D'].map((letter,i)=>[letter,q.options[orders[i]]])),answer:['A','B','C','D'][orders.indexOf(q.answer)]};}
function openTest(code){const t=getTest(String(code).toUpperCase());if(!t){toast('Không tìm thấy mã đề');return}currentExam=t;currentAnswers={};testResult=null;state.tab='test';persist();render()}
function answer(id,v){currentAnswers[id]=v;const x=document.getElementById('counter');if(x)x.textContent=Object.keys(currentAnswers).length+'/'+getFrozenQuestions(currentExam).length+' câu đã trả lời';}
function submitTest(){if(!currentExam)return;const student=(document.getElementById('student-name')?.value||'').trim().slice(0,100);if(!student){toast('Vui lòng nhập họ tên học sinh trước khi nộp bài.');return}const t=currentExam,details=getFrozenQuestions(t).map(q=>{const given=currentAnswers[q.id]||'',correct=given===q.answer;return {...q,given,answerLabel:q.answer,correct}});const score=Math.round(details.filter(x=>x.correct).length*1000/details.length)/100;testResult={code:t.code,title:t.title,grade:t.grade,student,details,score,date:new Date().toLocaleString('vi-VN')};state.attempts.push(structuredClone(testResult));persist();currentExam=null;render();}
function testView(){if(testResult){const r=testResult;return `${heading('Kết quả đã nộp','Đã tự động lưu vào mục Kết quả kiểm tra trên thiết bị.') }<div class="panel"><span class="pill ok">ĐÃ NỘP VÀ LƯU KẾT QUẢ</span><h2>${esc(r.student)} – ${esc(r.title)}</h2><div class="score">${r.score}<small>/10</small></div><p>Đúng ${r.details.filter(q=>q.correct).length}/${r.details.length} câu. <button class="btn secondary" onclick="navigate('results')">Xem lịch sử kết quả →</button></p>${r.details.map((q,i)=>`<div class="resultitem"><b>Câu ${i+1} • ${q.correct?'Đúng':'Chưa đúng'}</b><h4>${esc(q.stem)}</h4>${Object.entries(q.options||{}).map(([k,v])=>`<p>${k}. ${esc(v)}</p>`).join('')}<p><b>Em chọn:</b> ${esc(q.given||'Bỏ trống')} • <b>Đáp án:</b> ${esc(q.answerLabel)}</p><p>${esc(q.explanation||'Chưa có giải thích.')}</p></div>`).join('')}</div>`;}if(currentExam){const t=currentExam,qs=getFrozenQuestions(t);return `${heading('Làm bài kiểm tra','Đề đã trộn được lưu tự động. Nộp xong có ngay điểm và lời giải.') }<div class="panel"><span class="pill">${esc(t.kind)}</span><h3>${esc(t.title)} – Mã ${esc(t.code)}</h3><p>Hóa ${t.grade} • ${esc(t.chapter||'Tổng hợp')} • ${esc(t.lesson||'Toàn chương')}</p><label class="field">Họ tên học sinh<input id="student-name" placeholder="Nhập họ tên trước khi nộp" autocomplete="name"/></label><p id="counter" class="muted">0/${qs.length} câu đã trả lời</p>${qs.map((q,i)=>`<div class="q"><span class="pill">Câu ${i+1} • ${level(q.difficulty)}</span><h4>${esc(q.stem)}</h4><div class="opts">${Object.entries(q.options||{}).map(([k,v])=>`<label class="opt"><input type="radio" name="q${i}" onchange="answer('${q.id}','${k}')"/><b>${k}.</b> ${esc(v)}</label>`).join('')}</div></div>`).join('')}<button class="btn" onclick="submitTest()">Nộp bài • Xem ngay kết quả</button></div>`;}return `${heading('Làm bài kiểm tra','Danh sách mã đề vừa tạo được cập nhật tự động, không cần nhập lại.') }<div class="panel"><div class="row"><label class="field">Nhập mã đề nếu cần<input id="code" placeholder="DE..."/></label><button class="btn" onclick="openTest(document.getElementById('code').value)">Mở bài</button></div>${state.exams.length?`<h3>Đề đã sẵn sàng (${state.exams.length})</h3>${state.exams.slice().reverse().map(t=>`<div class="history-item"><span>Hóa ${t.grade} • ${esc(t.title)} • ${esc(t.lesson||t.chapter||'Tổng hợp')}<br><b>Mã: ${esc(t.code)}</b> • ${getFrozenQuestions(t).length} câu</span><button class="btn secondary" onclick="openTest('${t.code}')">Làm ngay</button></div>`).join('')}`:'<p class="notice">Chưa có đề. Mở Tạo và trộn đề để tạo bộ đề trước.</p>'}</div>`;}
function results(){const attempts=state.attempts||[],avg=attempts.length?Math.round(attempts.reduce((s,x)=>s+x.score,0)/attempts.length*100)/100:0;return `${heading('Kết quả kiểm tra','Mỗi lần nộp bài được lưu và hiển thị ngay; bản demo chỉ lưu trên thiết bị.') }<div class="metrics"><div class="metric"><small>Số bài đã nộp</small><strong>${attempts.length}</strong></div><div class="metric"><small>Học sinh phân biệt theo tên (ước tính)</small><strong>${new Set(attempts.map(x=>x.student)).size}</strong></div><div class="metric"><small>Điểm TB</small><strong>${avg}</strong><span>/10</span></div><div class="metric"><small>Số mã đề đã tạo</small><strong>${state.exams.length}</strong></div></div><div class="panel"><div class="tablewrap"><table><tr><th>Họ tên</th><th>Khối</th><th>Đề/mã</th><th>Điểm</th><th>Số đúng</th><th>Thời gian</th></tr>${attempts.slice().reverse().map(x=>`<tr><td>${esc(x.student||'Chưa ghi')}</td><td>${x.grade||''}</td><td>${esc(x.title)}<br>${esc(x.code)}</td><td><b>${x.score}/10</b></td><td>${x.details.filter(y=>y.correct).length}/${x.details.length}</td><td>${esc(x.date)}</td></tr>`).join('')}</table></div>${attempts.length?'':'<p class="muted">Chưa có kết quả.</p>'}</div>`;}
function ai(){return `${heading('Trợ lý AI và giải bài tập Hóa học','AI được gọi qua API máy chủ ở bản online; tệp index.html không chứa khóa API để đảm bảo an toàn.') }<div class="panel"><label class="field">Nhập bài tập hoặc câu hỏi<textarea id="ask" placeholder="Ví dụ: Phân tích sai lầm khi tính pH của dung dịch HCl 0,01 M..."></textarea></label><div class="row"><button class="btn" onclick="makePrompt()">Sao chép câu lệnh rồi mở ChatGPT</button><a href="https://chatgpt.com/" target="_blank" rel="noreferrer" class="btn secondary">Mở trực tiếp ChatGPT ↗</a></div><div id="promptResult"></div></div><div class="notice warning">Đây là bản dùng thử không kết nối Gemini. Hệ thống triển khai Next.js có trợ lý AI qua GEMINI_API_KEY đặt tại máy chủ. Câu trả lời của AI cần giáo viên kiểm tra.</div>`}
function makePrompt(){const x=document.getElementById('ask').value.trim();if(!x){toast('Hãy nhập bài tập trước.');return}const prompt='Đóng vai giáo viên Hóa học THPT, giải bài theo từng bước, có phương trình cân bằng, đơn vị đúng, chỉ ra lỗi sai thường gặp và ghi nhớ ngắn gọn. Bài tập: '+x;const node=document.getElementById('promptResult');node.innerHTML='<pre style="white-space:pre-wrap;background:#f4f9fd;padding:14px;border-radius:10px;line-height:1.7;font-size:12px">'+esc(prompt)+'</pre>';navigator.clipboard?.writeText(prompt).then(()=>toast('Đã sao chép câu lệnh.'),()=>{});}
function practice(){const rows=shuffle(filteredDemo().filter(q=>q.verified===true&&q.practice_enabled===true&&q.answer)).slice(0,4);return `${heading('Bài tập tương tác tự luyện','Luyện tập mẫu, sau mỗi câu nhận lời giải. Không tính vào điểm kiểm tra.') }<div class="panel"><div class="row"><label class="field">Khối lớp<select onchange="setGrade(this.value)">${[10,11,12].map(x=>`<option value="${x}" ${x===state.grade?'selected':''}>Hóa ${x}</option>`).join('')}</select></label><label class="field">Chương KNTT<select onchange="setChapter(this.value)">${chapterOptionsDemo()}</select></label><label class="field">Bài KNTT<select onchange="setLesson(this.value)">${lessonOptionsDemo()}</select></label></div>${rows.map((q,i)=>`<div class="q"><span class="pill">${level(q.difficulty)}</span><h4>Câu ${i+1}. ${esc(q.stem)}</h4><div class="opts">${Object.entries(q.options).map(([k,v])=>`<button class="btn secondary" style="text-align:left" onclick="practiceFeedback(this,${Number(k===q.answer)},'${esc(q.answer)}',${i})">${k}. ${esc(v)}</button>`).join('')}</div><div id="pf-${i}" class="notice" style="display:none">Đáp án: ${esc(q.answer)}. ${esc(q.explanation)}</div></div>`).join('')}</div>`}
function practiceFeedback(btn,correct,answer,i){const n=document.getElementById('pf-'+i);n.style.display='block';n.innerHTML='<b>'+(correct?'Chính xác!':'Chưa đúng, xem lại.')+'</b> '+n.textContent;}
function docs(){return `${heading('Tài liệu tham khảo online','Ưu tiên nguồn đáng tin cậy, kiểm tra điều kiện phản ứng và ghi rõ xuất xứ.') }<div class="cards">${links.map(([name,url])=>`<a class="quick" target="_blank" rel="noreferrer" href="${url}"><div class="ic">▤</div><strong>${esc(name)}</strong><span>Mở tài liệu tham khảo trực tuyến ↗</span></a>`).join('')}</div><div class="panel"><h3>Tra cứu chủ đề Hóa học trên Wikipedia</h3><div class="row"><label class="field">Từ khóa<input id="search" placeholder="Ví dụ: liên kết hóa học" value="${esc(state.lesson||'')}"/></label><button class="btn" onclick="window.open('https://vi.wikipedia.org/wiki/Special:Search?search='+encodeURIComponent(document.getElementById('search').value),'_blank','noopener,noreferrer')">Tìm kiếm online ↗</button></div><p class="muted">Wikipedia có thể chứa nội dung chưa được kiểm chứng; cần đối chiếu SGK, IUPAC, PubChem.</p></div>`}
// EduPlan chemistry helpers - educational arithmetic, neutral formula equations.
const MASSES={H:1.008,He:4.003,Li:6.94,Be:9.012,B:10.81,C:12.011,N:14.007,O:15.999,F:18.998,Ne:20.180,Na:22.990,Mg:24.305,Al:26.982,Si:28.085,P:30.974,S:32.06,Cl:35.45,Ar:39.948,K:39.098,Ca:40.078,Sc:44.956,Ti:47.867,V:50.942,Cr:51.996,Mn:54.938,Fe:55.945,Co:58.933,Ni:58.693,Cu:63.546,Zn:65.38,Ga:69.723,Ge:72.630,As:74.922,Se:78.971,Br:79.904,Kr:83.798,Rb:85.468,Sr:87.62,Ag:107.868,Cd:112.414,Sn:118.710,I:126.904,Ba:137.327,Pt:195.084,Au:196.967,Hg:200.592,Pb:207.2};
function mapAdd(to,from,m=1){for(const [k,n] of Object.entries(from))to[k]=(to[k]||0)+n*m;}
function parseUnit(formula){
 let i=0;function digits(){let x='';while(/[0-9]/.test(formula[i]||'')&&i<formula.length)x+=formula[i++];return x?Number(x):1}
 function seq(closer=null){const items={};while(i<formula.length){const c=formula[i];if(closer&&c===closer){i++;return items}if(c==='('||c==='['){i++;mapAdd(items,seq(c==='('?')':']'),digits());continue}if(/[A-Z]/.test(c)){let symbol=formula[i++];while(/[a-z]/.test(formula[i]||'')&&i<formula.length)symbol+=formula[i++];if(!MASSES[symbol])throw Error('Không nhận diện nguyên tố '+symbol);mapAdd(items,{[symbol]:digits()});continue}throw Error('Kí hiệu không hợp lệ ở vị trí '+(i+1));}if(closer)throw Error('Thiếu dấu đóng '+closer);return items}
 return seq();
}
function parseFormula(value){let x=String(value||'').trim().replace(/\s+/g,'').replace(/[·•]/g,'.');if(!x||x.length>90)throw Error('Công thức trống hoặc quá dài.');const all={};for(const part of x.split('.')){const mt=part.match(/^(\d+)?(.*)$/),mul=Number(mt[1]||1);if(!part||mul<1||mul>100||!mt[2])throw Error('Không hợp lệ: '+part);mapAdd(all,parseUnit(mt[2]),mul)}return all}
function molarMass(f){const elements=parseFormula(f);const mass=Object.entries(elements).reduce((sum,[el,num])=>sum+MASSES[el]*num,0);return {formula:f,elements,mass:Math.round(mass*10000)/10000,unit:'g/mol'};}
function gcd(a,b){a=a<0n?-a:a;b=b<0n?-b:b;while(b){const t=a%b;a=b;b=t}return a||1n}
function lcm(a,b){return a/gcd(a,b)*b}
function fraction(n,d=1n){if(d===0n)throw Error('Chia cho 0');if(d<0n){n=-n;d=-d}const g=gcd(n,d);return [n/g,d/g]}
const add=(a,b)=>fraction(a[0]*b[1]+b[0]*a[1],a[1]*b[1]);
const neg=a=>[-a[0],a[1]];const sub=(a,b)=>add(a,neg(b));
const mul=(a,b)=>fraction(a[0]*b[0],a[1]*b[1]);
const div=(a,b)=>fraction(a[0]*b[1],a[1]*b[0]);
function balanceEquation(input){
 const eq=String(input||'').trim();if(eq.length>220)throw Error('Phương trình quá dài.');const sides=eq.split(/\s*(?:->|→|=)\s*/);if(sides.length!==2)throw Error('Nhập phương trình dạng H2 + O2 -> H2O');
 const left=sides[0].split(/\s+\+\s+|\s*\+\s*/).map(x=>x.trim()),right=sides[1].split(/\s+\+\s+|\s*\+\s*/).map(x=>x.trim());const list=[...left,...right];if(list.length<2||list.length>12||list.some(x=>!x))throw Error('Số chất không hợp lệ.');
 const comps=list.map(v=>parseFormula(v.replace(/^\d+\s*/,'').replace(/\((aq|s|l|g)\)$/i,'')));
 const elements=[...new Set(comps.flatMap(x=>Object.keys(x)))];const rows=elements.map(el=>comps.map((v,j)=>fraction(BigInt((v[el]||0)*(j<left.length?1:-1)))));const n=list.length, pivots=[];let r=0;
 for(let c=0;c<n&&r<rows.length;c++){let p=r;while(p<rows.length&&rows[p][c][0]===0n)p++;if(p===rows.length)continue;[rows[p],rows[r]]=[rows[r],rows[p]];const v=rows[r][c];for(let j=c;j<n;j++)rows[r][j]=div(rows[r][j],v);for(let i=0;i<rows.length;i++)if(i!==r&&rows[i][c][0]!==0n){let k=rows[i][c];for(let j=c;j<n;j++)rows[i][j]=sub(rows[i][j],mul(k,rows[r][j]));}pivots.push(c);r++}
 const free=Array.from({length:n},(_,i)=>i).filter(c=>!pivots.includes(c));if(!free.length)throw Error('Không tìm được hệ số bảo toàn nguyên tố.');const coeff=Array.from({length:n},()=>fraction(1n));for(let i=pivots.length-1;i>=0;i--){let v=fraction(0n);for(let j=pivots[i]+1;j<n;j++)v=add(v,mul(rows[i][j],coeff[j]));coeff[pivots[i]]=neg(v)}let denom=1n;for(const a of coeff)denom=lcm(denom,a[1]);let vals=coeff.map(x=>x[0]*(denom/x[1]));if(vals.every(x=>x<0n))vals=vals.map(x=>-x);if(vals.some(x=>x<=0n))throw Error('Phản ứng này cần hệ số khác hoặc có ion/nhóm đặc biệt. Công cụ hỗ trợ phương trình phân tử trung hòa đơn giản.');const factor=vals.reduce((x,y)=>gcd(x,y));vals=vals.map(x=>x/factor);if(vals.some(x=>x>99999n))throw Error('Hệ số quá lớn.');const text=(a,i)=>`${vals[i]===1n?'':vals[i].toString()}${a}`;return {coefficients:vals.map(x=>Number(x)),equation:left.map((x,i)=>text(x,i)).join(' + ')+' → '+right.map((x,i)=>text(x,left.length+i)).join(' + '),elements};
}
function solutionMolarity(moles,volumeLitres){const n=Number(moles),v=Number(volumeLitres);if(!Number.isFinite(n)||!Number.isFinite(v)||n<0||v<=0)throw Error('n ≥ 0 và V (lít) > 0.');return {concentration:n/v,unit:'mol/L'}}


