function pickRandom(){const list=[...new Set(document.getElementById('students').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean))].slice(0,300);localStorage.setItem('eduplan_names_59',document.getElementById('students').value);if(!list.length){toast('Vui lòng nhập danh sách tên.');return}randomLeft=randomLeft.filter(x=>list.includes(x));if(!randomLeft.length)randomLeft=list.slice();const ar=new Uint32Array(1),limit=Math.floor(4294967296/randomLeft.length)*randomLeft.length;do{crypto.getRandomValues(ar)}while(ar[0]>=limit);let n=ar[0]%randomLeft.length;lastPick=randomLeft.splice(n,1)[0];document.getElementById('random-focus').textContent=lastPick;}
