function hub69History(){
 const practice=(P68.history||[]).flatMap(h=>(h.answers||[]).map(a=>({...a,grade:h.config?.grade||h.grade,chapter:h.config?.chapter||'',lesson:h.config?.lesson||''})));
 const focused=(SPDATA.history||[]).flatMap(h=>(h.responses||[]).map(a=>({...a,grade:h.config?.grade||'',chapter:h.config?.chapter||'',lesson:h.config?.lesson||''})));
 const all=[...practice,...focused],graded=all.filter(a=>typeof a.correct==='boolean'),correct=graded.filter(a=>a.correct===true),wrong=[...new Set(graded.filter(a=>a.correct===false).map(x=>x.id||x.question_id).filter(Boolean))];
 return {sessions:(P68.history||[]).length+(SPDATA.history||[]).length,answered:all.length,graded:graded.length,correct:correct.length,wrong:wrong.length,accuracy:graded.length?Math.round(correct.length*100/graded.length):null};
}
